import json
import os

TODO_FILE = "todo_list.json"

def load_todos():
    """todo_list.json에서 Todo 목록을 불러옵니다. 파일이 없으면 빈 리스트를 반환합니다."""
    if not os.path.exists(TODO_FILE):
        return []
    try:
        with open(TODO_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except json.JSONDecodeError:
        print("경고: Todo 파일이 손상되어 새 목록으로 초기화합니다.")
        return []

def save_todos(todos):
    """Todo 목록을 todo_list.json 파일에 저장합니다."""
    with open(TODO_FILE, 'w', encoding='utf-8') as f:
        json.dump(todos, f, indent=4, ensure_ascii=False)

def add_todo(task_description):
    """새로운 Todo 항목을 추가합니다."""
    todos = load_todos()
    new_todo = {
        "id": len(todos) + 1 if todos else 1,
        "task": task_description,
        "done": False
    }
    todos.append(new_todo)
    save_todos(todos)
    return new_todo

def view_todos():
    """현재 Todo 목록을 조회합니다."""
    todos = load_todos()
    if not todos:
        print("등록된 할 일 목록이 없습니다.")
        return ""

    output = ["--- 할 일 목록 ---"]
    for todo in todos:
        status = "[완료]" if todo["done"] else "[진행]"
        output.append(f"{todo['id']}. {status} {todo['task']}")

    return "\n".join(output)

def main():
    """CLI 실행을 위한 메인 함수 (테스트 목적으로는 간소화)"""
    import sys
    if len(sys.argv) < 2:
        print("Usage: todo_cli.py <command> [arguments]")
        print("Commands: add \"할 일 내용\", view")
        return

    command = sys.argv[1]

    if command == "add":
        if len(sys.argv) < 3:
            print("오류: 추가할 할 일 내용을 지정해야 합니다.")
            return
        task_desc = " ".join(sys.argv[2:])
        add_todo(task_desc)
        print(f"✅ 할 일 추가 완료: {task_desc}")

    elif command == "view":
        output = view_todos()
        print(output)

    else:
        print(f"알 수 없는 명령어: {command}")

