    todos = load_todos()
    # ID는 현재 목록의 크기 + 1로 가정하고 부여 (간단 버전)
    new_id = len(todos) + 1 if todos else 1
    new_todo = {
        "id": new_id,
        "task": task_description,
        "done": False
    }
    todos.append(new_todo)
    save_todos(todos)
    return new_todo

